import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, smoothstep, float, mix, length, uniform, texture } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, PointLight, AmbientLight } = ctx.THREE;

  const group = new Group();
  // Node position from config
  group.position.set(0, 1.6, 0);

  // Set up palette from config colors
  const inkColor = ctx.THREE.Color.NAMES ? new ctx.THREE.Color('#16161d') : new ctx.THREE.Color('#16161d');
  const paperColor = new ctx.THREE.Color('#e8ecf2');
  const accentColor = new ctx.THREE.Color('#ff2a38');
  const surfaceColor = new ctx.THREE.Color('#0b0b10');

  // Interactive state uniforms
  const hoverUniform = uniform(0.0);

  // Capsule geometry
  const width = 1.8;
  const height = 0.5;
  const geometry = new PlaneGeometry(width, height, 1, 1);

  // Material with TSL Shader logic
  const material = new MeshStandardNodeMaterial({
    transparent: true,
    roughness: 0.45,
    metalness: 0.5,
    roughnessMap: null
  });

  // Load the texture from assets
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.roughnessMap = tex;
      material.needsUpdate = true;
    });
  }

  // Define Capsule SDF layout
  const aspect = float(width / height);
  const p = uv().sub(0.5).mul(vec2(aspect, float(1.0)));
  const halfW = float((width / height) * 0.5 - 0.25);

  // Capsule distance field
  const d = length(p.sub(vec2(p.x.clamp(halfW.negate(), halfW), float(0.0)))).sub(float(0.24));

  // Anti-aliased mask
  const mask = smoothstep(float(0.01), float(0.0), d);

  // Base background (ink / surface mix)
  const baseBg = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), vec3(inkColor.r, inkColor.g, inkColor.b), float(0.5));

  // Accent glowing edge border (intensifies on hover)
  const edgeWidth = mix(float(0.04), float(0.05), hoverUniform);
  const edgeMask = smoothstep(float(0.0), float(0.01), d).mul(smoothstep(edgeWidth, edgeWidth.sub(float(0.015)), d));
  const glowEdge = vec3(accentColor.r, accentColor.g, accentColor.b).mul(edgeMask).mul(mix(float(1.2), float(2.2), hoverUniform));

  // Combine texture if loaded
  const finalDiffuse = mix(baseBg, glowEdge, edgeMask);

  // Apply inputs to material nodes
  material.colorNode = vec4(finalDiffuse, mask);

  const badgeMesh = new Mesh(geometry, material);
  badgeMesh.castShadow = true;
  group.add(badgeMesh);

  // Add discrete local lighting (Key + Rim)
  const keyLight = new PointLight('#e8ecf2', 1.0, 5);
  keyLight.position.set(1, 1, 2);
  group.add(keyLight);

  const rimLight = new PointLight('#ff2a38', 0.8, 4);
  rimLight.position.set(-1, -1, 1.5);
  group.add(rimLight);

  // Shadow plane
  const shadowGeometry = new PlaneGeometry(width * 1.3, height * 1.5);
  const shadowMaterial = new MeshStandardNodeMaterial({
    transparent: true,
    opacity: 0.4
  });
  const shadowUv = uv().sub(0.5);
  const shadowDist = length(shadowUv.mul(vec2(float(1.5), float(1.0))));
  shadowMaterial.colorNode = vec4(vec3(0.0), smoothstep(float(0.5), float(0.1), shadowDist).mul(float(0.55)));

  const shadowMesh = new Mesh(shadowGeometry, shadowMaterial);
  shadowMesh.position.set(0, -0.05, -0.1);
  group.add(shadowMesh);

  // Animation timelines
  let hoverTl = null;
  let clickTl = null;

  // Interaction Handlers
  const handlers = {
    pointerover: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(badgeMesh.position, { y: 0.12, z: 0.15, duration: 0.35, ease: 'power3.out' });
      hoverTl.to(shadowMesh.position, { y: -0.15, z: -0.2, scaleX: 0.9, scaleY: 0.9, duration: 0.35, ease: 'power3.out' }, 0);
      hoverTl.to(hoverUniform, { value: 1.0, duration: 0.35, ease: 'power2.out' }, 0);
    },
    pointerout: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(badgeMesh.position, { y: 0.0, z: 0.0, duration: 0.45, ease: 'power3.out' });
      hoverTl.to(shadowMesh.position, { y: -0.05, z: -0.1, scaleX: 1.0, scaleY: 1.0, duration: 0.45, ease: 'power3.out' }, 0);
      hoverTl.to(hoverUniform, { value: 0.0, duration: 0.45, ease: 'power2.out' }, 0);
    },
    pointerdown: () => {
      if (clickTl) clickTl.kill();
      clickTl = gsap.timeline();
      clickTl.to(badgeMesh.scale, { x: 0.92, y: 0.92, duration: 0.1, ease: 'power2.out' });
      clickTl.to(badgeMesh.scale, { x: 1.0, y: 1.0, duration: 0.25, ease: 'back.out(2.5)' });

      ctx.emit('hub-collection.select', { id: 'collection-badge' });
    }
  };

  badgeMesh.userData.handlers = handlers;

  // Cleanup block
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (clickTl) clickTl.kill();
    geometry.dispose();
    material.dispose();
    shadowGeometry.dispose();
    shadowMaterial.dispose();
  };

  // Run initial programmatic fly-through rise-in transition
  gsap.fromTo(badgeMesh.position, 
    { y: -0.4, z: -0.5 }, 
    { y: 0.0, z: 0.0, duration: 0.85, ease: 'power4.out', delay: 0.1 }
  );

  return group;
}
